const markup="<div class=\"page-shell dao-reading origin-dao\" data-origin-dao=\"\">\n<nav aria-label=\"当前位置\" class=\"breadcrumbs\"><a href=\"#/tian\">天道</a><span aria-hidden=\"true\">/</span><a href=\"#/map?focus=origin\">本源</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">道：源头</span></nav>\n<section aria-labelledby=\"opening-question\" class=\"origin-opening\" id=\"origin-opening\"><div class=\"prose origin-opening-copy\"><p class=\"eyebrow\">从根本，理解万物</p><h2 id=\"opening-question\">万物的源头，到底是什么？</h2><blockquote>吾不知其名，字之曰道。<cite>《道德经》第二十五章</cite></blockquote></div><figure class=\"origin-opening-art\"><img alt=\"金色光流自中央源头展开，水墨般的星云与星系汇于同一片宇宙\" class=\"ink-art\" decoding=\"async\" fetchpriority=\"high\" height=\"425\" src=\"/assets/origin-dao-20261102/source-header-20261104.webp\" width=\"1774\"/></figure><div class=\"prose origin-opening-map\"><blockquote class=\"\">道生一，一生二，二生三，三生万物。<cite>《道德经》第四十二章</cite></blockquote><p class=\"origin-caption\">下文从“道”开始，依次理解根源、潜能、差异与共同成物。</p><details class=\"action-fold dao-fold origin-atlas-fold\"><summary>本源主线：道、一、二、三与万物</summary><div class=\"action-prose\"><div class=\"opening-atlas\"><p class=\"opening-hint\">选择下方概念，查看它在这条主线中的含义。</p><svg aria-labelledby=\"origin-diagram-title origin-diagram-desc\" class=\"opening-diagram\" id=\"origin-diagram\" role=\"img\" viewbox=\"0 25 1100 180\">\n<title id=\"origin-diagram-title\">从道、一、二、三到万物的五个概念位置</title>\n<desc id=\"origin-diagram-desc\">五个图形由一条柔和的曲线联系：根源、未分化的整体、差异、两极共存的关系、万千具体形态。这是认识层次而不是宇宙形成的物理时间轴。</desc>\n<defs>\n<radialgradient id=\"origin-dao-glow\"><stop offset=\"0\" stop-color=\"#ddc89e\" stop-opacity=\".9\"></stop><stop offset=\".55\" stop-color=\"#d6e6d9\" stop-opacity=\".8\"></stop><stop offset=\"1\" stop-color=\"#f3f4e9\" stop-opacity=\".1\"></stop></radialgradient>\n<radialgradient id=\"origin-yi-glow\"><stop offset=\"0\" stop-color=\"#aacdb3\" stop-opacity=\".75\"></stop><stop offset=\"1\" stop-color=\"#dbe8d9\" stop-opacity=\".1\"></stop></radialgradient>\n<lineargradient id=\"origin-pair-gradient\"><stop stop-color=\"#406f68\"></stop><stop offset=\"1\" stop-color=\"#d0ad78\"></stop></lineargradient>\n</defs>\n<path d=\"M67 113 C192 12 360 195 548 111 S856 19 1036 111\" fill=\"none\" stroke=\"#c7d5c9\" stroke-linecap=\"round\" stroke-width=\"2\"></path>\n<path d=\"M67 133 C230 218 370 35 556 134 S882 214 1036 130\" fill=\"none\" stroke=\"#dcd8c6\" stroke-dasharray=\"5 8\" stroke-width=\"1.5\"></path>\n<g aria-hidden=\"true\" class=\"origin-node active\" data-origin-node=\"0\" transform=\"translate(108 112)\">\n<circle fill=\"url(#origin-dao-glow)\" r=\"63\"></circle>\n<circle fill=\"none\" r=\"41\" stroke=\"#a98b56\" stroke-opacity=\".76\" stroke-width=\"1.5\"></circle>\n<circle fill=\"none\" r=\"28\" stroke=\"#809989\" stroke-dasharray=\"2 6\" stroke-width=\"1.4\"></circle>\n<circle fill=\"#718f7c\" r=\"8\"></circle><circle fill=\"#f8f4e9\" r=\"3\"></circle>\n</g>\n<g aria-hidden=\"true\" class=\"origin-node\" data-origin-node=\"1\" transform=\"translate(332 112)\">\n<circle fill=\"url(#origin-yi-glow)\" r=\"60\"></circle>\n<path d=\"M-31 16 C-27 -35 20 -39 29 -3 C36 29 -22 43 -27 10\" fill=\"none\" opacity=\".65\" stroke=\"#5c896e\" stroke-width=\"2\"></path>\n<path d=\"M-34 -3 Q2 -21 35 6 M-20 31 Q10 7 28 -27\" fill=\"none\" opacity=\".58\" stroke=\"#9faf96\" stroke-linecap=\"round\" stroke-width=\"1.6\"></path>\n</g>\n<g aria-hidden=\"true\" class=\"origin-node\" data-origin-node=\"2\" transform=\"translate(552 112)\">\n<circle fill=\"#f6f5ec\" r=\"58\" stroke=\"#a2b8a8\" stroke-width=\"1.2\"></circle>\n<path d=\"M0 -49 A49 49 0 0 1 0 49 A24.5 24.5 0 0 1 0 0 A24.5 24.5 0 0 0 0 -49Z\" fill=\"#4f7e70\"></path>\n<path d=\"M0 -49 A49 49 0 0 0 0 49 A24.5 24.5 0 0 0 0 0 A24.5 24.5 0 0 1 0 -49Z\" fill=\"#e4d4b6\"></path>\n<circle cy=\"-24.5\" fill=\"#e4d4b6\" r=\"5\"></circle><circle cy=\"24.5\" fill=\"#4f7e70\" r=\"5\"></circle>\n</g>\n<g aria-hidden=\"true\" class=\"origin-node\" data-origin-node=\"3\" transform=\"translate(768 112)\">\n<circle fill=\"#f6f5ed\" r=\"58\" stroke=\"#a0b6a6\" stroke-width=\"1.2\"></circle>\n<ellipse cx=\"-17\" cy=\"-3\" fill=\"#5b8877\" opacity=\".52\" rx=\"30\" ry=\"41\" transform=\"rotate(-25 -17 -3)\"></ellipse>\n<ellipse cx=\"17\" cy=\"-3\" fill=\"#cbb083\" opacity=\".62\" rx=\"30\" ry=\"41\" transform=\"rotate(25 17 -3)\"></ellipse>\n<path d=\"M0 -43 C31 -13 31 15 0 43 C-31 15 -31 -13 0 -43Z\" fill=\"none\" stroke=\"#537666\" stroke-width=\"2\"></path>\n<circle fill=\"#f7f4ec\" r=\"8\" stroke=\"#527d6d\" stroke-width=\"1.5\"></circle>\n</g>\n<g aria-hidden=\"true\" class=\"origin-node\" data-origin-node=\"4\" fill=\"none\" stroke=\"#729886\" stroke-width=\"1.6\" transform=\"translate(993 112)\">\n<path d=\"M-41 -13 L-13 -32 L20 -27 L44 -2 L27 27 L-12 37 L-39 13 Z\" stroke-opacity=\".53\"></path>\n<path d=\"M-13 -32 L3 2 L44 -2 M-41 -13 L3 2 L-12 37 M3 2 L27 27\" stroke-opacity=\".7\"></path>\n<circle cx=\"-41\" cy=\"-13\" fill=\"#538171\" r=\"7\"></circle><circle cx=\"-13\" cy=\"-32\" fill=\"#b99b64\" r=\"5\"></circle><circle cx=\"20\" cy=\"-27\" fill=\"#84a590\" r=\"8\"></circle><circle cx=\"44\" cy=\"-2\" fill=\"#b99b64\" r=\"5\"></circle><circle cx=\"27\" cy=\"27\" fill=\"#608b7e\" r=\"10\"></circle><circle cx=\"-12\" cy=\"37\" fill=\"#cbb083\" r=\"6\"></circle><circle cx=\"3\" cy=\"2\" fill=\"#fffdf7\" r=\"5\"></circle>\n</g>\n</svg><div aria-label=\"主线概念选择\" class=\"opening-path\">\n<button aria-controls=\"path-note\" aria-pressed=\"true\" data-path=\"0\" type=\"button\"><span class=\"glyph\">道</span><span class=\"meaning\">源头</span></button>\n<button aria-controls=\"path-note\" aria-pressed=\"false\" data-path=\"1\" type=\"button\"><span class=\"glyph\">一</span><span class=\"meaning\">混沌</span></button>\n<button aria-controls=\"path-note\" aria-pressed=\"false\" data-path=\"2\" type=\"button\"><span class=\"glyph\">二</span><span class=\"meaning\">阴阳</span></button>\n<button aria-controls=\"path-note\" aria-pressed=\"false\" data-path=\"3\" type=\"button\"><span class=\"glyph\">三</span><span class=\"meaning\">既阴又阳</span></button>\n<button aria-controls=\"path-note\" aria-pressed=\"false\" data-path=\"4\" type=\"button\"><span class=\"glyph\">万物</span><span class=\"meaning\">具体形态</span></button>\n</div><div aria-atomic=\"true\" aria-live=\"polite\" class=\"origin-readout\" id=\"path-note\"><strong>道 · 具有觉知与创造性的源头</strong><span>从存在的根本，理解觉知与创造的位置。这是1.1首先展开的内容。</span></div></div></div></details></div></section>\n<header class=\"page-heading\"><span class=\"eyebrow\">TIAN / 本源 / 1.1</span><h1>道：源头</h1><p class=\"page-intro\">道，是具有宇宙性觉知与创造性的源头。<br/>万物的存在、认识与生成，由此获得共同的根本。</p></header>\n<div class=\"article-layout\"><aside class=\"article-toc\"><span class=\"eyebrow\">本页内容</span><button data-scroll=\"thesis\" type=\"button\">道：存在、觉知与创造的根本</button><button data-scroll=\"whole\" type=\"button\">一切万有：源头与万物相通</button><button data-scroll=\"knowing\" type=\"button\">自知与经验：知道如何成为亲历</button><button data-scroll=\"expression\" type=\"button\">创造：本源的丰富获得表达</button><button data-scroll=\"grounds\" type=\"button\">以觉知与创造理解本源</button><button data-scroll=\"one\" type=\"button\">道生一：从根源走向潜能</button></aside><article class=\"prose origin-body\"><section aria-labelledby=\"thesis-title\" class=\"origin-section\" id=\"thesis\"><h2 id=\"thesis-title\">道：存在、觉知与创造的根本</h2>\n<p>追问一棵树的来历，会遇到种子、土壤、阳光与生长；继续追问，又会触及更广阔的条件与过程。由此，一个根本问题出现了：万物得以存在与生成，依于怎样的根源？</p><p>《三道哲学》以“道”回答这个问题，并进一步主张：<strong>道本身具有宇宙性的觉知与创造性。</strong></p><p>根源性说明它与一切存在的关系；觉知性说明认识与经验在这套世界观中的根本地位；创造性说明源头能够表达、展开为具体形式。</p><p>这三个方面共同构成我们对道的理解。后文要逐步说明：它们如何相连，又如何帮助我们理解世界。</p><p class=\"philosophy-note\">“宇宙性”指觉知被置于本源的位置。这里没有预先为道指定人的感官、语言、性格或思考方式。</p>\n<figure class=\"origin-figure\"><div class=\"eyebrow\">同一个源头 · 三个理解入口</div><div class=\"triad-diagram\"><div class=\"triad-center\">道<small>同一个根本</small></div><div class=\"triad-branches\"><span class=\"triad-branch selected\" data-aspect-mark=\"0\">根源性</span><span class=\"triad-branch\" data-aspect-mark=\"1\">觉知性</span><span class=\"triad-branch\" data-aspect-mark=\"2\">创造性</span></div></div><div aria-label=\"源头的三个方面\" class=\"origin-choices\"><button aria-pressed=\"true\" class=\"origin-choice\" data-aspect=\"0\">存在的根本</button><button aria-pressed=\"false\" class=\"origin-choice\" data-aspect=\"1\">觉知的根本</button><button aria-pressed=\"false\" class=\"origin-choice\" data-aspect=\"2\">创造的根本</button></div><p aria-live=\"polite\" class=\"origin-readout\" id=\"aspect-note\"><strong>万物何以存在？</strong><br/>道指向具体存在与生成所依于的根本。</p><figcaption class=\"origin-caption\">切换的是理解的侧面。三个方面共同描述道，图中没有安排它们先后产生。</figcaption></figure>\n</section><section aria-labelledby=\"whole-title\" class=\"origin-section\" id=\"whole\"><h2 id=\"whole-title\">一切万有：源头与万物相通</h2>\n<p>《与神对话》第一卷的起源叙述，从“一切万有”开始：起初，全部存在就是这个整体，除此之外没有别的。<a class=\"link-ref\" href=\"#ref-cwg\">[1]</a></p><p>这为源头与万物的关系提供了一个清楚的起点：既然一切都在其中，万物的展开也只能发生于整体之内。</p><p>因此，在本篇的理解中，树、星、水与生命，都与根源保持联系。它们各有具体的样子，任何一种样子又不足以代表源头的全部。</p><p>原书还提醒：理解源头，需要同时容纳可见与不可见。沿着这条思路，眼前已经显现的形式，也无法穷尽尚可展开的可能。</p><blockquote class=\"origin-emphasis\">万物属于源头的展开。<br/>源头的丰富，超出眼前的一形。</blockquote><blockquote class=\"\">道可道，非常道。<br/>名可名，非常名。<cite>《道德经》第一章<a class=\"link-ref\" href=\"#ref-dao\">[2]</a></cite></blockquote><p>一个名称可以指向它。我们还需要从不同形态及其联系中，继续认识这个名字所指的根本。</p>\n<figure class=\"origin-figure\"><div class=\"eyebrow\">同一幅画 · 局部与整体</div><div class=\"art-window\"><img alt=\"同一山水中的松树、流水和星光，观察框随选择移动\" class=\"ink-art\" data-art=\"whole\" decoding=\"async\" loading=\"lazy\" src=\"/assets/origin-dao-20261102/whole.webp\"/><div aria-hidden=\"true\" id=\"art-focus\"></div></div><div aria-label=\"选择观察范围\" class=\"origin-choices\"><button aria-pressed=\"true\" class=\"origin-choice\" data-window=\"0\">看树</button><button aria-pressed=\"false\" class=\"origin-choice\" data-window=\"1\">看水</button><button aria-pressed=\"false\" class=\"origin-choice\" data-window=\"2\">看星</button><button aria-pressed=\"false\" class=\"origin-choice\" data-window=\"3\">看全景</button></div><p aria-live=\"polite\" class=\"origin-readout\" id=\"window-note\"><strong>看见树，是认识一种具体形态。</strong><br/>画面仍保留树之外的河流、山峦与星光。</p><figcaption class=\"origin-caption\">山水帮助体会局部与整体的关系；整幅画仍是一个有限的意象。</figcaption></figure>\n</section><section aria-labelledby=\"knowing-title\" class=\"origin-section\" id=\"knowing\"><h2 id=\"knowing-title\">自知与经验：知道如何成为亲历</h2>\n<p>《与神对话》接着提出一个关键区别：<strong>概念上的知道，与亲身发生的经验，具有不同的内容。</strong>它用慷慨和善意说明：理解一种品质、认为自己具有这种品质，与在行动中亲历它，仍然有所不同。<a class=\"link-ref\" href=\"#ref-cwg\">[1]</a></p><p>例如，一个人理解善意，也知道自己愿意帮助别人。当他实际扶起跌倒的人，善意就进入了一次具体的行动、关系与感受。这个例子说明“知道”与“经验”的区别。</p>\n<figure class=\"origin-figure\"><div class=\"eyebrow\">一个例子 · 看清认识内容怎样增加</div><div class=\"knowledge-flow\"><div class=\"knowledge-node current\" data-knowledge-mark=\"0\"><b>知</b><span>理解善意</span><small>概念与自我认识</small></div><span aria-hidden=\"true\" class=\"flow-arrow\">→</span><div class=\"knowledge-node\" data-knowledge-mark=\"1\"><b>行</b><span>扶起跌倒的人</span><small>品质进入行动</small></div><span aria-hidden=\"true\" class=\"flow-arrow\">→</span><div class=\"knowledge-node\" data-knowledge-mark=\"2\"><b>历</b><span>亲历这次善意</span><small>具体关系与感受</small></div></div><div aria-label=\"知道、表达与经验\" class=\"origin-choices\"><button aria-pressed=\"true\" class=\"origin-choice\" data-knowledge=\"0\">概念上的知道</button><button aria-pressed=\"false\" class=\"origin-choice\" data-knowledge=\"1\">行动中的表达</button><button aria-pressed=\"false\" class=\"origin-choice\" data-knowledge=\"2\">亲身的经验</button></div><p aria-live=\"polite\" class=\"origin-readout\" id=\"knowledge-note\"><strong>知道：我理解善意，也知道自己愿意帮助别人。</strong><br/>这份认识已经存在；接下来还可以使它进入一次具体行动。</p><figcaption class=\"origin-caption\">日常例子用于区分两类认识。它帮助阅读原书，并不代替关于宇宙性觉知的论证。</figcaption></figure>\n<p>回到原书，它一面说整体缺少外部参照，一面又说整体已经知道自己就是全部存在。连读这两层意思，才能看清它要讲的推进：<strong>自知已经成立，某种性质的相对经验仍有待展开。</strong></p><p>因此，在我们的源头观中，道的觉知性属于它的本性。具体的差异与关系，则让某种性质能够以特定的方式被经验。</p><blockquote class=\"origin-emphasis\">自知，使源头能够知道自身。<br/>经验，使其中的丰富具体发生。</blockquote><p>于是，后文真正需要解释的问题出现了：当整体之外没有他者，怎样在整体内部形成差异与参照？差异与参照的关系，将在1.3“二：极性”中展开。</p>\n</section><section aria-labelledby=\"expression-title\" class=\"origin-section\" id=\"expression\"><h2 id=\"expression-title\">创造：本源的丰富获得表达</h2>\n<p>理解了知道与经验的区别，创造便有了进一步的意义：它让源头所具有的可能，进入具体的表达与经验。</p><p>《与神对话》明确区分“需要”与“欲望”：无所需要，并不意味着没有创造的意愿。原书继而把欲望与选择创造联系起来。<a class=\"link-ref\" href=\"#ref-desire\">[3]</a></p><p>本篇沿此理解：<strong>本自具足说明源头的完整；创造性说明这份丰富能够展开。</strong>表达的发生，本身不必意味着根源有所欠缺。</p><p>“为什么仍愿创造”的动因，将在1.3中集中讨论。这里先确立创造性的含义：源头具有使形式、关系与经验得以展开的能力。</p><p>《道德经》说“道法自然”。借此对读，我们进一步理解创造性如何贯穿万物依条件而生、依关系而变的过程。源头与世界的关系，也就延伸到持续的生成之中。<a class=\"link-ref\" href=\"#ref-dao\">[2]</a></p>\n<figure class=\"origin-figure\"><div class=\"eyebrow\">从潜在，到可见的表达</div><div class=\"reveal-art\"><img alt=\"淡墨中的山峦与枝叶逐渐清晰\" class=\"ink-art\" data-art=\"reveal\" decoding=\"async\" loading=\"lazy\" src=\"/assets/origin-dao-20261102/expression.webp\"/><div class=\"reveal-veil\" id=\"reveal-veil\"></div></div><label class=\"reveal-label\" for=\"reveal-slider\">拖动，观察形态逐渐清晰 <output id=\"reveal-value\">70%</output></label><input aria-describedby=\"reveal-caption\" id=\"reveal-slider\" max=\"100\" min=\"0\" type=\"range\" value=\"70\"/><figcaption class=\"origin-caption\" id=\"reveal-caption\">以淡墨与成形体会“表达”。百分比表示插画显示程度；画面是哲学意象。</figcaption></figure>\n</section><section aria-labelledby=\"grounds-title\" class=\"origin-section\" id=\"grounds\"><h2 id=\"grounds-title\">以觉知与创造理解本源</h2>\n<p>当我们谈“世界”，既谈到了存在的事物，也谈到了认识世界的经验，以及新的形式如何出现。《三道哲学》试图从同一个根本理解这三者。</p><p>把觉知放在本源的位置，意味着经验在这套世界观中具有根本地位。把创造性放在本源的位置，则使根源与具体世界之间形成展开、表达的联系。由此，存在、认识和创造被放进一条连贯的解释路径。</p><p>这也是Nous对本篇的意义。《赫尔墨斯文集》以神圣心智参与宇宙生成的叙述，提供了将心智与根源相连的思想资源。本篇以<strong>Nous对应道／源头</strong>，据此深化觉知与创造的关系。<a class=\"link-ref\" href=\"#ref-nous\">[4]</a></p>\n<div class=\"source-route\"><div><span class=\"eyebrow\">《道德经》</span><h3>根源与生发</h3><p>以道理解万物的根本，从“自然”理解生成的方式。</p></div><div><span class=\"eyebrow\">《与神对话》</span><h3>自知与经验</h3><p>以一切万有为起点，连接整体、自我认识与创造性表达。</p></div><div><span class=\"eyebrow\">Nous</span><h3>心智与生成</h3><p>以神圣心智的叙述，加深对源头觉知性与创造性的理解。</p></div></div>\n<p>这些材料共同帮助我们提出自己的判断。我们的理由在于：这一源头观能够把存在、经验与创造之间的关系作为同一个问题持续追究。</p><p>它的解释力还取决于下一步能否把关系讲清：<strong>宇宙性的觉知如何与个体经验相连，整体怎样展开为彼此有别的存在，潜能又怎样进入具体生成。</strong>这些问题构成后续研究的方向。</p><p class=\"philosophy-note\">这里给出的是采用这一哲学立场的理由。觉知的根本地位不会仅由“经验存在”自动推出，经典之间的相通也不能代替对具体关系的解释。</p>\n</section><section aria-labelledby=\"one-title\" class=\"origin-section\" id=\"one\"><h2 id=\"one-title\">道生一：从根源走向潜能</h2>\n<p>到这里，我们对道形成了一个正面理解：它是存在的根源，本身具有觉知，也具有创造性的表达能力；万物与它相通，具体形式不能穷尽它。</p><p>现在，问题向前推进一步：<strong>当这种创造能力尚未展开为彼此有别的万物时，整体以怎样的方式存在？</strong></p><p>本篇把这一未分化的整体称为“一／混沌”：还没有成为具体的万物，却具有形成万物的能力。我们以Hyle对应这一位置。</p>\n<div class=\"chapter-bridge\"><div><span class=\"eyebrow\">1.1 ／ 道 · Nous</span><h3>生成的根源</h3><p>具有觉知与创造性的根本。</p></div><div aria-hidden=\"true\" class=\"bridge-arrow\">→</div><div><span class=\"eyebrow\">1.2 ／ 一 · Hyle</span><h3>未分化的潜能</h3><p>尚未成形，却能够形成万物。</p></div></div><p>“道生一”围绕根源与这份潜能之间的关系展开。随后，1.3再说明差异、参照与共同成物，最后回到个体的经验与选择。</p>\n</section>\n<details class=\"action-fold dao-fold dao-sources\" id=\"sources\"><summary>原文与出处</summary><div class=\"action-prose\"><p>下列原典帮助解释本篇的源头观。根源性、觉知性与创造性的组织，以及 Nous 与道、Hyle 与一的对应，属于《三道哲学》的综合阐释。PDF页数按所引版本从第一页起算。</p><ol class=\"source-list\"><li id=\"ref-cwg\"><strong>[1] Conversations with God，Book 1，PDF31—33页；Book 2，PDF162页。</strong><p>第一卷依次讨论概念上的知道与经验、一切万有、外部参照不存在、整体内部的分化及可见／不可见。正文以中文转述；“扶起跌倒的人”用于说明善意如何进入具体行动。</p></li><li id=\"ref-dao\"><strong>[2] 《道德经》第一、二十五章。</strong><p>经文采用《道德经·细雨视角》所收版本。“道可道，非常道。名可名，非常名”及“道法自然”保留原句。道的宇宙性觉知是本篇主动采用的立场。</p></li><li id=\"ref-desire\"><strong>[3] Conversations with God，Book 1，PDF65—66页；Communion with God，PDF19页。</strong><p>原书直接区分需要与欲望，并把欲望、选择与创造相连。“完整”与“表达”的关系在本文中据此阐释，完整动因在1.3展开。</p></li><li id=\"ref-nous\"><strong>[4] 《赫尔墨斯文集》I.4—9、V.1；G. R. S. Mead英译，1906。</strong><p>I.6的神圣心智与V.1关于使万物显现的叙述，是本节对读入口。Nous→道、Hyle→一沿用本篇对根源与潜能的理解。可回查<a href=\"https://www.scryway.com/library/texts/hermetica-mead/1\" rel=\"noopener noreferrer\" target=\"_blank\">第一篇</a>与<a href=\"https://www.scryway.com/library/texts/hermetica-mead/5\" rel=\"noopener noreferrer\" target=\"_blank\">第五篇</a>。</p></li></ol><p>水墨插画呈现局部与整体、未显与显现的意象。</p></div></details>\n<details class=\"action-fold dao-fold dao-sources\"><summary>进一步的问题：这套源头观还需要说明什么？</summary><div class=\"action-prose\"><h3>宇宙性觉知与个体经验怎样相连？</h3><p>将觉知置于本源，确立了它的根本地位；这还需要进一步解释个体视角、经验差异与彼此独立性。不能用“都在整体之中”代替这些具体关系。</p><h3>自知与经验的区分，解释到了哪里？</h3><p>它帮助理解原书的认识层次，避免从“没有外部参照”直接跳到“完全没有自知”。它尚未完整定义宇宙性觉知的结构；是否采用“无对象的原初觉知”等更强表述，需要另行论证。</p><h3>本自具足是否意味着一切经验都已完成？</h3><p>正文以根本的完整与具体经验的发生作区分。若进一步主张全知已经包含所有经验，则仍需说明创造增加什么，不能仅凭换用“表达”一词消除这个问题。</p><h3>创造性怎样进入具体世界？</h3><p>这里建立根源、潜能与表达的解释方向；潜能与形式的关系、差异如何产生，将随1.2与1.3继续深化。图中的箭头表示概念承接。</p><h3>这一立场的性质</h3><p>这是《三道哲学》采用的本体论主张。支持理由主要来自解释目标、概念关系与原典对读；没有把宇宙性觉知标为已获科学验证的结论，也不从参照的必要性推出具体痛苦或伤害必然合理。</p></div></details>\n</article></div></div>";
export const originDaoPage=()=>markup;

export function initOriginDao(root){
 const page=root.querySelector('[data-origin-dao]');if(!page)return ()=>{};
 const listeners=[];const on=(el,type,fn)=>{el.addEventListener(type,fn);listeners.push(()=>el.removeEventListener(type,fn));};

const $=s=>page.querySelector(s);
function group(selector,fn){page.querySelectorAll(selector).forEach(button=>on(button,'click',()=>{page.querySelectorAll(selector).forEach(b=>b.setAttribute('aria-pressed',String(b===button)));fn(Number(Object.values(button.dataset)[0]));}));}
const aspectNotes=['<strong>万物何以存在？</strong><br>道指向具体存在与生成所依于的根本。','<strong>觉知处于什么位置？</strong><br>在本篇的源头观中，觉知是根本性质；认识与经验由此进入对存在的理解。','<strong>丰富的形式怎样获得来路？</strong><br>道的创造性，使根源与具体形式之间具有展开、表达的联系。'];
group('[data-aspect]',i=>{page.querySelectorAll('[data-aspect-mark]').forEach(e=>e.classList.toggle('selected',Number(e.dataset.aspectMark)===i));$('#aspect-note').innerHTML=aspectNotes[i];});
const positions=[[3,9,32,66],[43,54,45,40],[75,1,22,24],[1,1,98,98]];
const windowNotes=['<strong>看见树，是认识一种具体形态。</strong><br>画面仍保留树之外的河流、山峦与星光。','<strong>把目光移向河流。</strong><br>流动的水呈现另一种面貌，整幅画的连续性始终保留。','<strong>将窗口移向星光。</strong><br>所关注的局部发生改变，共同背景仍在。','<strong>把局部放回同一幅画。</strong><br>树、水与星光彼此有别，又共同参与整体。'];
group('[data-window]',i=>{const f=$('#art-focus');['left','top','width','height'].forEach((k,n)=>f.style[k]=positions[i][n]+'%');f.style.boxShadow=i===3?'none':'0 0 0 900px #efeee8aa';$('#window-note').innerHTML=windowNotes[i];});
const knowledgeNotes=['<strong>知道：我理解善意，也知道自己愿意帮助别人。</strong><br>这份认识已经存在；接下来还可以使它进入一次具体行动。','<strong>表达：在这一次相遇中，我扶起跌倒的人。</strong><br>已有的认识仍在，善意开始以具体行动发生。','<strong>经验：我亲历了这次帮助中的关系与感受。</strong><br>经验使善意成为具体经历；它没有抹去原先的知道。'];
group('[data-knowledge]',i=>{page.querySelectorAll('[data-knowledge-mark]').forEach(e=>{const n=Number(e.dataset.knowledgeMark);e.classList.toggle('current',n<=i);});$('#knowledge-note').innerHTML=knowledgeNotes[i];});
on($('#reveal-slider'),'input',e=>{const n=Number(e.target.value);$('#reveal-veil').style.opacity=String(1-n/100);$('#reveal-value').textContent=n+'%';});
const originNotes=[['道 · 具有觉知与创造性的源头','从存在的根本，理解觉知与创造的位置。这是1.1首先展开的内容。'],['一 · 尚未分化的混沌','还没有成为具体的万物，却具有形成万物的能力。1.2从这里解释潜能。'],['二 · 阴阳、差异与参照','整体之内出现此与彼，经验由此获得参照。1.3从差异与极性展开。'],['三 · 阴、阳、既阴又阳','阴、阳与既阴又阳构成“三”；整体不能被孤立的任一端穷尽。这一关系仍在1.3中解释。'],['万物 · 共同构成的丰富形态','阴、阳、既阴又阳共同构成万物，具体关系与变化使形态各不相同。']];
function chooseOrigin(i){page.querySelectorAll('[data-path]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.path)===i)));page.querySelectorAll('[data-origin-node]').forEach(n=>n.classList.toggle('active',Number(n.dataset.originNode)===i));const note=page.querySelector('#path-note');note.replaceChildren();const title=document.createElement('strong'),body=document.createElement('span');title.textContent=originNotes[i][0];body.textContent=originNotes[i][1];note.append(title,body);}
page.querySelectorAll('[data-path]').forEach(b=>on(b,'click',()=>chooseOrigin(Number(b.dataset.path))));
 const onReference=e=>{const a=e.target.closest('a.link-ref');if(!a)return;e.preventDefault();const d=page.querySelector('#sources');d.open=true;page.querySelector(a.getAttribute('href'))?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});};on(page,'click',onReference);
 return ()=>listeners.forEach(dispose=>dispose());
}
